import { z } from "zod";

/*
 * "Spiegami questa lettera": a letter from the Agenzia delle Entrate, INPS, the Comune or a
 * collection agency, read by the AI and explained in plain Italian, with what to do and by when.
 * The picture is sent to the AI provider only to be read, never stored. The answer is generated by
 * an AI and says so (AI Act, art. 50): it's a first explanation, not legal or tax advice.
 */

export const LETTER_TYPES = [
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "application/pdf",
] as const;
export type LetterType = (typeof LETTER_TYPES)[number];

/** Anthropic accepts images up to 5 MB each; a letter photo is well under. */
export const LETTER_MAX_BYTES = 5 * 1024 * 1024;

export const LETTER_INSTRUCTIONS = `Sei l'assistente di Orbitly, un'app italiana di finanza personale. Ricevi la foto o il PDF di una lettera (Agenzia delle Entrate, INPS, Comune, Agenzia delle Entrate-Riscossione, ASL, banca, una multa) e la spieghi a una persona che non conosce il linguaggio burocratico.

Rispondi SOLO con un oggetto JSON valido, senza testo prima o dopo, con questi campi:
- "readable": true se riesci a leggere una lettera, false altrimenti.
- "sender": chi la manda, in breve (es. "Agenzia delle Entrate").
- "kind": che cos'è, con il nome tecnico tra parentesi se c'è (es. "Una richiesta di pagare un'imposta (avviso bonario)").
- "summary": cosa dice, in 2-4 frasi semplici, dando del tu.
- "amount": l'importo da pagare o da ricevere in euro come numero, oppure null.
- "deadline": la scadenza come data "AAAA-MM-GG" se è scritta, altrimenti null.
- "deadlineText": la scadenza come la direbbe una persona (es. "entro 60 giorni da quando l'hai ricevuta"), oppure null.
- "steps": da 1 a 5 cose da fare, in ordine, frasi brevi.
- "documents": da 0 a 5 documenti da preparare.
- "urgency": "alta" se c'è una scadenza vicina o un rischio di sanzioni, "media", oppure "bassa" se è solo informativa.
- "caution": un avvertimento utile oppure null. Se la lettera chiede di pagare con un link, un SMS, una ricarica o a un IBAN privato, avverti che può essere una truffa e di verificare sul sito ufficiale dell'ente.

Regole: non inventare dati che non leggi; se un campo non c'è usa null o una lista vuota. Non dare consulenza legale o fiscale personalizzata: quando la situazione è complicata, suggerisci di farsi aiutare da un CAF, un patronato o un professionista. Non ripetere codici fiscali, indirizzi o altri dati personali che leggi nella lettera.`;

export const letterSchema = z.object({
  readable: z.boolean(),
  sender: z.string().max(200).nullable().default(null),
  kind: z.string().max(300).nullable().default(null),
  summary: z.string().max(1500).nullable().default(null),
  amount: z.number().nonnegative().max(10_000_000).nullable().default(null),
  deadline: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/)
    .nullable()
    .catch(null)
    .default(null),
  deadlineText: z.string().max(300).nullable().default(null),
  steps: z.array(z.string().max(400)).max(5).default([]),
  documents: z.array(z.string().max(300)).max(5).default([]),
  urgency: z.enum(["alta", "media", "bassa"]).catch("media").default("media"),
  caution: z.string().max(600).nullable().default(null),
});

export type LetterExplanation = z.infer<typeof letterSchema>;

/** The JSON in the model's reply, tolerating a stray code fence or words around it. */
export function parseLetterReply(text: string): LetterExplanation | null {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try {
    const parsed = letterSchema.safeParse(JSON.parse(text.slice(start, end + 1)));
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}
